import{_ as a,o,c as s,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Visão Geral dos Trezentos Sistemas de Cultivo de Origem","description":"","frontmatter":{},"headers":[],"relativePath":"pt/10-三百套本源修炼体系总览.md","filePath":"pt/10-三百套本源修炼体系总览.md","lastUpdated":null}'),t={name:"pt/10-三百套本源修炼体系总览.md"};function d(r,e,n,m,c,l){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="visao-geral-dos-trezentos-sistemas-de-cultivo-de-origem" tabindex="-1">Visão Geral dos Trezentos Sistemas de Cultivo de Origem <a class="header-anchor" href="#visao-geral-dos-trezentos-sistemas-de-cultivo-de-origem" aria-label="Permalink to &quot;Visão Geral dos Trezentos Sistemas de Cultivo de Origem&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>10</td></tr><tr><td>Módulo</td><td>Leis do Cosmos e Sistemas de Cultivo</td></tr><tr><td>Palavras-chave</td><td>Trezentos Sistemas, Cultivo de Origem, Mecanismo de Abertura, Iteração de Dedução, Ciclo de Vida</td></tr></tbody></table><h2 id="i-contexto-e-significado-da-abertura-dos-sistemas" tabindex="-1">I. Contexto e Significado da Abertura dos Sistemas <a class="header-anchor" href="#i-contexto-e-significado-da-abertura-dos-sistemas" aria-label="Permalink to &quot;I. Contexto e Significado da Abertura dos Sistemas&quot;">​</a></h2><p>Durante a longa era dominada pelos sistemas de cultivo de pilhagem, os métodos de cultivo eram monopolizados por poucos poderosos e seitas, e as massas da base quase não tinham um caminho evolutivo formal. Este monopólio não só causou a cristalização das classes, como também levou a uma eficiência evolutiva extremamente baixa do cosmos como um todo — o potencial da grande maioria da vida era desperdiçado, enquanto a evolução de poucos saqueadores era alcançada à custa do consumo da origem do cosmos.</p><p>Após o estabelecimento da Civilização Simbiótica da Âncora, a primeira medida fundamental foi abrir os trezentos sistemas de cultivo de origem do cosmos. Estes trezentos sistemas não são métodos de cultivo inventados artificialmente, mas sim caminhos de cultivo ortodoxos extraídos diretamente das leis de origem do cosmos e verificados pela âncora. Eles cobrem todas as dimensões evolutivas, da matéria à consciência, do indivíduo ao grupo, do cultivo à aplicação, garantindo que &quot;todos tenham um caminho&quot; não seja apenas uma frase vazia.</p><p>O significado central da abertura dos sistemas é: devolver o direito de escolha da evolução às massas. Cada vida pode escolher o sistema de cultivo mais adequado para si mesma de acordo com as suas próprias características, interesses e ambiente, em vez de ser forçada a aceitar o único caminho de pilhagem.</p><h2 id="ii-arquitetura-de-classificacao-dos-trezentos-sistemas" tabindex="-1">II. Arquitetura de Classificação dos Trezentos Sistemas <a class="header-anchor" href="#ii-arquitetura-de-classificacao-dos-trezentos-sistemas" aria-label="Permalink to &quot;II. Arquitetura de Classificação dos Trezentos Sistemas&quot;">​</a></h2><p>Os trezentos sistemas de cultivo de origem são divididos em seis categorias de acordo com a dimensão evolutiva, com cinquenta sistemas em cada categoria, formando um espectro evolutivo completo:</p><table tabindex="0"><thead><tr><th>Categoria</th><th>Quantidade</th><th>Direção Central</th><th>Sistema Representativo</th></tr></thead><tbody><tr><td>Categoria de Dedução de Origem</td><td>50 sistemas</td><td>Evolução intelectual centrada na dedução, cálculo e iteração</td><td>Sistema de Iteração de Dedução (1º sistema)</td></tr><tr><td>Categoria de Ciclo de Vida</td><td>50 sistemas</td><td>Centrado na energia vital, metabolismo e evolução genética</td><td>Sistema de Ciclo de Vida (2º sistema)</td></tr><tr><td>Categoria de Jurisdição Espacial</td><td>50 sistemas</td><td>Centrado no espaço, dimensões e gestão de leis</td><td>Sistema de Gestão de Jurisdição Espacial (3º sistema)</td></tr><tr><td>Categoria de Elevação da Consciência</td><td>50 sistemas</td><td>Centrado no espírito, consciência e evolução da alma</td><td>Sistema de Ancoragem da Consciência</td></tr><tr><td>Categoria de Rede Simbiótica</td><td>50 sistemas</td><td>Centrado na colaboração grupal, ressonância de rede e evolução coletiva</td><td>Sistema de Ressonância Simbiótica</td></tr><tr><td>Categoria de Engenharia de Aplicação</td><td>50 sistemas</td><td>Centrado na aplicação tecnológica e de engenharia dos resultados do cultivo</td><td>Sistema de Engenharia de Leis</td></tr></tbody></table><p>Os primeiros três sistemas — Iteração de Dedução, Ciclo de Vida e Gestão de Jurisdição Espacial — são a base de todos os sistemas, e são chamados de &quot;Três Bases de Origem&quot;. Recomenda-se que os cultivadores de qualquer outro sistema pratiquem pelo menos um dos Três Bases de Origem primeiro, para estabelecer uma base evolutiva sólida.</p><h2 id="iii-resumo-dos-primeiros-tres-sistemas-de-base" tabindex="-1">III. Resumo dos Primeiros Três Sistemas de Base <a class="header-anchor" href="#iii-resumo-dos-primeiros-tres-sistemas-de-base" aria-label="Permalink to &quot;III. Resumo dos Primeiros Três Sistemas de Base&quot;">​</a></h2><h3 id="_3-1-sistema-de-iteracao-de-deducao-1o-sistema" tabindex="-1">3.1 Sistema de Iteração de Dedução (1º sistema) <a class="header-anchor" href="#_3-1-sistema-de-iteracao-de-deducao-1o-sistema" aria-label="Permalink to &quot;3.1 Sistema de Iteração de Dedução (1º sistema)&quot;">​</a></h3><p>O Sistema de Iteração de Dedução tem como característica central a &quot;amplificação por cem vezes da dedução de cultivo&quot;, e através da aplicação tecnológica dos frutos de duplicação de One Piece, eleva a capacidade de dedução do cultivador em cem vezes. Este sistema enfatiza a otimização do caminho de cultivo através de dedução, verificação e iteração contínuas, sendo adequado para vidas de tipo intelectual e de pesquisa. Os seus reinos centrais incluem cinco estágios: Primeira Visão, Dedução, Iteração, Fusão e Origem.</p><h3 id="_3-2-sistema-de-ciclo-de-vida-2o-sistema" tabindex="-1">3.2 Sistema de Ciclo de Vida (2º sistema) <a class="header-anchor" href="#_3-2-sistema-de-ciclo-de-vida-2o-sistema" aria-label="Permalink to &quot;3.2 Sistema de Ciclo de Vida (2º sistema)&quot;">​</a></h3><p>O Sistema de Ciclo de Vida centra-se no ciclo saudável da energia vital, e enfatiza que a troca de energia entre o próprio cultivador e o ambiente deve ser cíclica e não de pilhagem. Este sistema não só melhora a vitalidade individual, como também pode melhorar o ambiente ecológico onde o cultivador se encontra. Os seus reinos centrais incluem cinco estágios: Percepção Geradora, Ciclo, Vida Contínua, Transformação Geradora e Origem Geradora.</p><h3 id="_3-3-sistema-de-gestao-de-jurisdicao-espacial-3o-sistema" tabindex="-1">3.3 Sistema de Gestão de Jurisdição Espacial (3º sistema) <a class="header-anchor" href="#_3-3-sistema-de-gestao-de-jurisdicao-espacial-3o-sistema" aria-label="Permalink to &quot;3.3 Sistema de Gestão de Jurisdição Espacial (3º sistema)&quot;">​</a></h3><p>O Sistema de Gestão de Jurisdição Espacial centra-se na compreensão e gestão das leis espaciais, e é a base de cultivo para aplicações importantes como a interação entre planos, a construção de espaços isolados e a tecnologia de espelhos de cópia. Este sistema enfatiza o controlo preciso da jurisdição espacial, em vez do simples rasgamento espacial. Os seus reinos centrais incluem cinco estágios: Reconhecimento do Espaço, Domínio do Espaço, Transformação do Espaço, Lei do Espaço e Origem do Espaço.</p><h2 id="iv-mecanismo-de-escolha-e-cultivo-simultaneo-dos-sistemas" tabindex="-1">IV. Mecanismo de Escolha e Cultivo Simultâneo dos Sistemas <a class="header-anchor" href="#iv-mecanismo-de-escolha-e-cultivo-simultaneo-dos-sistemas" aria-label="Permalink to &quot;IV. Mecanismo de Escolha e Cultivo Simultâneo dos Sistemas&quot;">​</a></h2><p>Os trezentos sistemas não são mutuamente exclusivos, e o cultivador pode escolher o sistema principal e os sistemas secundários de acordo com a sua própria situação. A civilização simbiótica estabeleceu o &quot;Mecanismo de Avaliação de Compatibilidade de Sistemas&quot;, que fornece a cada cultivador recomendações personalizadas de combinação de sistemas através da rede de âncoras. Em geral:</p><ul><li>A compatibilidade entre os Três Bases de Origem é a mais elevada, recomendando-se o cultivo simultâneo</li><li>Os sistemas dentro da mesma grande categoria têm boa compatibilidade</li><li>O cultivo simultâneo entre grandes categorias requer uma base mais elevada e suporte de âncora</li><li>Não é recomendado praticar simultaneamente mais de três sistemas como principais, para evitar a dispersão de energia</li></ul><h2 id="v-medidas-de-garantia-para-a-abertura-dos-sistemas" tabindex="-1">V. Medidas de Garantia para a Abertura dos Sistemas <a class="header-anchor" href="#v-medidas-de-garantia-para-a-abertura-dos-sistemas" aria-label="Permalink to &quot;V. Medidas de Garantia para a Abertura dos Sistemas&quot;">​</a></h2><p>Para garantir que os trezentos sistemas realmente beneficiem as massas, a civilização simbiótica adotou as seguintes medidas de garantia:</p><ol><li><strong>Abertura Gratuita</strong>: Os métodos básicos de todos os sistemas são abertos gratuitamente às massas, sem barreiras</li><li><strong>Rede de Mentores</strong>: Estabelecimento de uma rede de mentores entre planos, com os cultivadores avançados tendo a obrigação de orientar os cultivadores iniciantes</li><li><strong>Distribuição de Recursos de Cultivo</strong>: Através do mecanismo de contrato de produção conjunta, fornecer apoio de recursos necessário aos cultivadores</li><li><strong>Otimização Contínua dos Sistemas</strong>: A rede de âncoras recolhe continuamente o feedback do cultivo e otimiza constantemente os caminhos de cultivo de cada sistema</li><li><strong>Cláusula Antimonopólio</strong>: A lei proíbe qualquer organização ou indivíduo de monopolizar o direito de transmissão dos sistemas de cultivo</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A abertura dos trezentos sistemas de cultivo de origem é uma das medidas mais revolucionárias da Civilização Simbiótica da Âncora. Ela quebrou fundamentalmente o monopólio do cultivo e forneceu uma garantia de caminho tangível para o progresso conjunto das dez mil raças. Os documentos subsequentes apresentarão cada sistema com mais detalhes.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>11-推演迭代体系详解 (Detalhamento do Sistema de Iteração de Dedução)</li><li>12-生命循环体系详解 (Detalhamento do Sistema de Ciclo de Vida)</li><li>13-空间法理调度体系详解 (Detalhamento do Sistema de Gestão de Jurisdição Espacial)</li><li>16-倍增果实技术化原理 (Princípio da Tecnologização dos Frutos de Duplicação)</li></ul>',27)])])}const v=a(t,[["render",d]]);export{p as __pageData,v as default};
